/**
 * Logger — Stylized ANSI Telemetry
 *
 * Color-coded terminal logger using raw ANSI escape codes.
 * Zero dependencies — no chalk, no picocolors.
 */

// ─── ANSI Escape Codes ──────────────────────────────────────

const RESET = '\x1b[0m';
const BOLD = '\x1b[1m';
const DIM = '\x1b[2m';

// Foreground colors
const FG_GREEN = '\x1b[32m';
const FG_YELLOW = '\x1b[33m';
const FG_CYAN = '\x1b[36m';
const FG_MAGENTA = '\x1b[35m';
const FG_RED = '\x1b[31m';
const FG_WHITE = '\x1b[37m';
const FG_GRAY = '\x1b[90m';

// Background colors (bright)
const BG_GREEN = '\x1b[42m';
const BG_MAGENTA = '\x1b[45m';
const BG_CYAN = '\x1b[46m';
const BG_YELLOW = '\x1b[43m';

export interface LoggerOptions {
  /** Disable all logging output */
  silent?: boolean;
  /** Include timestamps in log output */
  timestamps?: boolean;
}

export class Logger {
  private silent: boolean;
  private timestamps: boolean;

  constructor(options: LoggerOptions = {}) {
    this.silent = options.silent ?? false;
    this.timestamps = options.timestamps ?? false;
  }

  /**
   * 🧠 [LEARN] — Logged when updating Markov graph weights.
   */
  learn(fromRoute: string, toRoute: string, newWeight: number): void {
    if (this.silent) return;
    const prefix = `${BG_MAGENTA}${BOLD}${FG_WHITE} 🧠 LEARN ${RESET}`;
    const message = `${FG_MAGENTA}${fromRoute}${RESET} ${FG_GRAY}→${RESET} ${FG_MAGENTA}${toRoute}${RESET} ${DIM}(weight: ${newWeight})${RESET}`;
    this.print(prefix, message);
  }

  /**
   * 🔮 [PREDICT] — Logged when confidence crosses the threshold.
   */
  predict(currentRoute: string, predictedRoute: string, confidence: number): void {
    if (this.silent) return;
    const prefix = `${BG_CYAN}${BOLD}${FG_WHITE} 🔮 PREDICT ${RESET}`;
    const pct = `${(confidence * 100).toFixed(1)}%`;
    const message = `${FG_CYAN}${pct} confidence:${RESET} ${FG_WHITE}${currentRoute}${RESET} ${FG_GRAY}→${RESET} ${FG_CYAN}${BOLD}${predictedRoute}${RESET}${FG_GRAY}. Pre-fetching in background...${RESET}`;
    this.print(prefix, message);
  }

  /**
   * ⚡ [CLAIRVOYANT HIT] — Logged when serving a response from RAM.
   */
  hit(method: string, route: string, servedInMs: number, savedMs: number): void {
    if (this.silent) return;
    const prefix = `${BG_GREEN}${BOLD}${FG_WHITE} ⚡ CLAIRVOYANT HIT ${RESET}`;
    const message = `${FG_GREEN}Served ${method} ${route}${RESET} in ${BOLD}${FG_GREEN}${servedInMs.toFixed(2)}ms${RESET} ${FG_GRAY}(Saved ${FG_YELLOW}${savedMs.toFixed(0)}ms${FG_GRAY} DB roundtrip)${RESET}`;
    this.print(prefix, message);
  }

  /**
   * 🧹 [INVALIDATE] — Logged when a mutation clears a user's predictive cache.
   */
  invalidate(clientId: string, method: string, route: string, purgedCount: number): void {
    if (this.silent) return;
    const prefix = `${BG_YELLOW}${BOLD}${FG_WHITE} 🧹 INVALIDATE ${RESET}`;
    const message = `${FG_YELLOW}${method} ${route}${RESET} ${FG_GRAY}by ${clientId} — purged ${FG_RED}${purgedCount}${FG_GRAY} cached prediction(s)${RESET}`;
    this.print(prefix, message);
  }

  /**
   * ℹ️  [INFO] — General information messages.
   */
  info(message: string): void {
    if (this.silent) return;
    const prefix = `${FG_CYAN}${BOLD} ℹ️  INFO ${RESET}`;
    this.print(prefix, `${FG_WHITE}${message}${RESET}`);
  }

  /**
   * Print a formatted log line.
   */
  private print(prefix: string, message: string): void {
    const ts = this.timestamps
      ? `${FG_GRAY}[${new Date().toISOString()}]${RESET} `
      : '';
    console.log(`${ts}${prefix} ${message}`);
  }
}
