/**
 * Prefetcher — Non-Blocking Background Execution
 *
 * Dispatches a local loopback fetch() to the server's own port,
 * triggered via setImmediate() so it never blocks the active request.
 *
 * Injects `x-clairvoyant-prefetch: true` to prevent recursive predictions.
 * Stores the result in the LRU cache under `${clientId}:${method}:${route}`.
 */

import { LRUCache, type CachedResponse } from '../cache/LRUCache.js';

export interface PrefetchContext {
  /** The predicted route to pre-fetch (e.g. "/api/notifications") */
  predictedRoute: string;
  /** The HTTP method of the predicted request (always GET for pre-fetches) */
  method: string;
  /** The client's unique session identifier */
  clientId: string;
  /** The port the Express server is listening on */
  port: number;
  /** Headers to forward from the original request */
  forwardHeaders: Record<string, string>;
}

export class Prefetcher {
  private readonly cache: LRUCache;
  private inflight = new Set<string>();

  constructor(cache: LRUCache) {
    this.cache = cache;
  }

  /**
   * Schedule a non-blocking background pre-fetch via setImmediate().
   * Prevents duplicate in-flight requests for the same client+route.
   */
  schedule(ctx: PrefetchContext): void {
    const cacheKey = `${ctx.clientId}:${ctx.method}:${ctx.predictedRoute}`;

    // Don't duplicate in-flight pre-fetches
    if (this.inflight.has(cacheKey)) return;

    // Don't pre-fetch if already cached
    if (this.cache.get(cacheKey)) return;

    this.inflight.add(cacheKey);

    setImmediate(() => {
      this.executePrefetch(ctx, cacheKey).catch(() => {
        // Silently swallow errors — pre-fetch failures should never surface
      }).finally(() => {
        this.inflight.delete(cacheKey);
      });
    });
  }

  /**
   * Execute the actual loopback fetch to the local server.
   */
  private async executePrefetch(ctx: PrefetchContext, cacheKey: string): Promise<void> {
    const url = `http://127.0.0.1:${ctx.port}${ctx.predictedRoute}`;
    const startTime = performance.now();

    const headers: Record<string, string> = {
      'x-clairvoyant-prefetch': 'true',
      'accept': 'application/json',
    };

    // Forward authentication and session headers from the original request
    if (ctx.forwardHeaders['authorization']) {
      headers['authorization'] = ctx.forwardHeaders['authorization'];
    }
    if (ctx.forwardHeaders['cookie']) {
      headers['cookie'] = ctx.forwardHeaders['cookie'];
    }
    if (ctx.forwardHeaders['x-session-id']) {
      headers['x-session-id'] = ctx.forwardHeaders['x-session-id'];
    }

    const response = await fetch(url, {
      method: ctx.method,
      headers,
      signal: AbortSignal.timeout(5000), // 5s timeout for pre-fetch
    });

    const executionTimeMs = performance.now() - startTime;

    // Only cache successful JSON responses
    if (response.ok) {
      let body: unknown;
      try {
        body = await response.json();
      } catch {
        return; // Not JSON — skip caching
      }

      // Extract relevant response headers
      const responseHeaders: Record<string, string> = {};
      response.headers.forEach((value, key) => {
        if (key.startsWith('x-') || key === 'content-type') {
          responseHeaders[key] = value;
        }
      });

      const cached: CachedResponse = {
        status: response.status,
        headers: responseHeaders,
        body,
        executionTimeMs,
        cachedAt: Date.now(),
      };

      this.cache.put(cacheKey, cached);
    }
  }
}
