/**
 * MarkovGraph — The Predictive Brain
 *
 * Directed Weighted Graph built with nested Maps.
 * Each node is a normalized route (e.g. "GET:/api/dashboard").
 * Edges store transition counts to subsequent routes.
 *
 * Transition probability:
 *   P(Next | Current) = EdgeWeight(Current -> Next) / TotalOutgoingWeight(Current)
 */

export interface Prediction {
  route: string;
  probability: number;
}

export interface GraphSnapshot {
  nodes: string[];
  edges: Array<{
    from: string;
    to: string;
    weight: number;
    probability: number;
  }>;
  totalTransitions: number;
}

export class MarkovGraph {
  /**
   * Adjacency map: fromRoute -> (toRoute -> transitionCount)
   */
  private readonly graph: Map<string, Map<string, number>> = new Map();
  private totalTransitions = 0;

  /**
   * Record a transition from one route to another.
   * Increments the edge weight between the two nodes.
   */
  recordTransition(fromRoute: string, toRoute: string): void {
    if (!fromRoute || !toRoute || fromRoute === toRoute) return;

    let edges = this.graph.get(fromRoute);
    if (!edges) {
      edges = new Map<string, number>();
      this.graph.set(fromRoute, edges);
    }

    const currentWeight = edges.get(toRoute) ?? 0;
    edges.set(toRoute, currentWeight + 1);
    this.totalTransitions++;
  }

  /**
   * Predict the most likely next route from the current route.
   *
   * @param currentRoute       - The user's current normalized route
   * @param confidenceThreshold - Minimum probability to emit a prediction (default: 0.60)
   * @param minSamples          - Minimum total outgoing transitions required (default: 3)
   * @returns The predicted route and its probability, or null
   */
  predictNext(
    currentRoute: string,
    confidenceThreshold = 0.60,
    minSamples = 3,
  ): Prediction | null {
    const edges = this.graph.get(currentRoute);
    if (!edges || edges.size === 0) return null;

    // Sum all outgoing transition weights from the current node
    let totalOutgoing = 0;
    for (const weight of edges.values()) {
      totalOutgoing += weight;
    }

    // Require a minimum sample size before making predictions
    if (totalOutgoing < minSamples) return null;

    // Find the edge with the highest weight
    let bestRoute = '';
    let bestWeight = 0;
    for (const [route, weight] of edges) {
      if (weight > bestWeight) {
        bestWeight = weight;
        bestRoute = route;
      }
    }

    const probability = bestWeight / totalOutgoing;

    // Only return prediction if it meets the confidence threshold
    if (probability < confidenceThreshold) return null;

    return {
      route: bestRoute,
      probability,
    };
  }

  /**
   * Export the entire learned transition matrix for debugging / visualization.
   */
  getGraphSnapshot(): GraphSnapshot {
    const nodes = new Set<string>();
    const edges: GraphSnapshot['edges'] = [];

    for (const [from, edgeMap] of this.graph) {
      nodes.add(from);

      let totalOutgoing = 0;
      for (const w of edgeMap.values()) totalOutgoing += w;

      for (const [to, weight] of edgeMap) {
        nodes.add(to);
        edges.push({
          from,
          to,
          weight,
          probability: totalOutgoing > 0 ? weight / totalOutgoing : 0,
        });
      }
    }

    return {
      nodes: Array.from(nodes),
      edges,
      totalTransitions: this.totalTransitions,
    };
  }

  /**
   * Reset the graph (useful for testing).
   */
  reset(): void {
    this.graph.clear();
    this.totalTransitions = 0;
  }
}
