/**
 * Clairvoyant — Predictive "Negative Latency" Express Middleware
 *
 * Uses Markov Chains and an LRU Cache to predict and pre-fetch
 * a user's next API request before they click.
 *
 * Usage:
 *   import { Clairvoyant } from 'clairvoyant-js';
 *   app.use(Clairvoyant.observe());
 *
 * @module clairvoyant-js
 */

import type { Request, Response, NextFunction } from 'express';
import { MarkovGraph, type Prediction, type GraphSnapshot } from './engine/MarkovGraph.js';
import { LRUCache } from './cache/LRUCache.js';
import { Prefetcher } from './engine/Prefetcher.js';
import { SessionTracker } from './utils/identity.js';
import { Logger } from './utils/logger.js';

// ─── Public Types ───────────────────────────────────────────

export interface ClairvoyantOptions {
  /** Minimum prediction confidence to trigger a pre-fetch (0.0–1.0, default: 0.60) */
  confidenceThreshold?: number;
  /** Minimum outgoing samples before predictions are emitted (default: 3) */
  minSamples?: number;
  /** Maximum pre-fetched responses stored in the LRU cache (default: 500) */
  maxCacheSize?: number;
  /** Time-to-live in ms before an unconsumed prediction expires (default: 15000) */
  ttlMs?: number;
  /** Route prefixes excluded from graph tracking and pre-fetching (default: ['/health']) */
  ignorePaths?: string[];
  /** Enables color-coded ANSI telemetry logs in the terminal (default: true) */
  debug?: boolean;
  /**
   * Port the Express server is listening on (for loopback pre-fetch).
   * If omitted, auto-detected from the first incoming request.
   */
  port?: number;
}

export interface ClairvoyantStats {
  cache: {
    size: number;
    maxSize: number;
    hits: number;
    misses: number;
    hitRate: number;
    totalMsSaved: number;
  };
  graph: GraphSnapshot;
}

// ─── Singleton State ────────────────────────────────────────

let markovGraph: MarkovGraph;
let lruCache: LRUCache;
let prefetcher: Prefetcher;
let sessionTracker: SessionTracker;
let logger: Logger;
let detectedPort: number | null = null;

// Mutation methods that should trigger cache invalidation
const MUTATION_METHODS = new Set(['POST', 'PUT', 'PATCH', 'DELETE']);

// ─── Exported API ───────────────────────────────────────────

export const Clairvoyant = {
  /**
   * Create the Express middleware.
   * Initialize all internal systems on first call.
   */
  observe(options: ClairvoyantOptions = {}): (req: Request, res: Response, next: NextFunction) => void {
    const {
      confidenceThreshold = 0.60,
      minSamples = 3,
      maxCacheSize = 500,
      ttlMs = 15_000,
      ignorePaths = ['/health'],
      debug = true,
      port: explicitPort,
    } = options;

    // Initialize singletons
    markovGraph = new MarkovGraph();
    lruCache = new LRUCache({ maxSize: maxCacheSize, ttlMs });
    logger = new Logger({ silent: !debug });
    prefetcher = new Prefetcher(lruCache);
    sessionTracker = new SessionTracker();
    detectedPort = explicitPort ?? null;

    return function clairvoyantMiddleware(req: Request, res: Response, next: NextFunction): void {
      // ────────────────────────────────────────────────────
      // 1. LOOP GUARD: Skip pre-fetch requests entirely
      // ────────────────────────────────────────────────────
      if (req.headers['x-clairvoyant-prefetch'] === 'true') {
        next();
        return;
      }

      // Auto-detect port from the first real request
      if (detectedPort === null) {
        const addr = req.socket?.localPort;
        if (addr) {
          detectedPort = addr;
        }
      }

      // Skip excluded routes
      const requestUrl = req.originalUrl || req.url;
      if (ignorePaths.some((prefix) => requestUrl.startsWith(prefix))) {
        next();
        return;
      }

      const clientId = sessionTracker.extractClientId(req);
      const method = req.method.toUpperCase();
      const normalizedRoute = `${method}:${requestUrl}`;

      // ────────────────────────────────────────────────────
      // 2. MUTATION INVALIDATION
      // ────────────────────────────────────────────────────
      if (MUTATION_METHODS.has(method)) {
        const purged = lruCache.invalidateUser(clientId);
        if (purged > 0) {
          logger.invalidate(clientId, method, requestUrl, purged);
        }

        // Still record the transition for the Markov graph
        const lastRoute = sessionTracker.getLastRoute(clientId);
        if (lastRoute) {
          markovGraph.recordTransition(lastRoute, normalizedRoute);
          logger.learn(lastRoute, normalizedRoute, 0);
        }
        sessionTracker.setLastRoute(clientId, normalizedRoute);

        next();
        return;
      }

      // ────────────────────────────────────────────────────
      // 3. CACHE CHECK (GET requests)
      // ────────────────────────────────────────────────────
      const cacheKey = `${clientId}:${method}:${requestUrl}`;
      const cached = lruCache.get(cacheKey);

      if (cached) {
        const serveStart = performance.now();

        // Still record transition and predict forward
        const lastRoute = sessionTracker.getLastRoute(clientId);
        if (lastRoute) {
          markovGraph.recordTransition(lastRoute, normalizedRoute);
          logger.learn(lastRoute, normalizedRoute, 0);
        }
        sessionTracker.setLastRoute(clientId, normalizedRoute);

        // Trigger prediction for the NEXT step
        const prediction = markovGraph.predictNext(
          normalizedRoute,
          confidenceThreshold,
          minSamples,
        );
        if (prediction && detectedPort !== null) {
          triggerPrefetch(prediction, clientId, detectedPort, req);
        }

        const servedInMs = performance.now() - serveStart;
        const savedMs = cached.executionTimeMs;

        // Set response headers
        res.set('X-Clairvoyant', 'HIT');
        res.set('X-Clairvoyant-Saved-Ms', savedMs.toFixed(2));

        logger.hit(method, requestUrl, servedInMs, savedMs);

        res.status(cached.status).json(cached.body);
        return;
      }

      // ────────────────────────────────────────────────────
      // 4. CACHE MISS — Monkey-patch res.json to capture output
      // ────────────────────────────────────────────────────
      const originalJson = res.json.bind(res);

      res.json = function clairvoyantPatchedJson(body?: unknown): Response {
        // Restore original before calling it
        res.json = originalJson;

        // Record the response finishing
        res.once('finish', () => {
          // Only learn + predict on successful responses
          if (res.statusCode >= 200 && res.statusCode < 300) {
            // Record Markov transition
            const lastRoute = sessionTracker.getLastRoute(clientId);
            if (lastRoute) {
              markovGraph.recordTransition(lastRoute, normalizedRoute);
              logger.learn(lastRoute, normalizedRoute, 0);
            }
            sessionTracker.setLastRoute(clientId, normalizedRoute);

            // Predict and pre-fetch
            const prediction = markovGraph.predictNext(
              normalizedRoute,
              confidenceThreshold,
              minSamples,
            );

            if (prediction && detectedPort !== null) {
              triggerPrefetch(prediction, clientId, detectedPort, req);
            }
          }
        });

        // Set header to indicate this was a miss
        res.set('X-Clairvoyant', 'MISS');

        return originalJson(body);
      } as typeof res.json;

      next();
    };
  },

  /**
   * Get current cache and graph statistics.
   */
  getStats(): ClairvoyantStats {
    return {
      cache: lruCache?.getStats() ?? {
        size: 0,
        maxSize: 0,
        hits: 0,
        misses: 0,
        hitRate: 0,
        totalMsSaved: 0,
      },
      graph: markovGraph?.getGraphSnapshot() ?? {
        nodes: [],
        edges: [],
        totalTransitions: 0,
      },
    };
  },

  /**
   * Reset all internal state (for testing).
   */
  reset(): void {
    markovGraph?.reset();
    lruCache?.clear();
    sessionTracker?.destroy();
    detectedPort = null;
  },
};

// ─── Internal Helpers ───────────────────────────────────────

function triggerPrefetch(
  prediction: Prediction,
  clientId: string,
  port: number,
  req: Request,
): void {
  // The predicted route is stored as "GET:/api/foo", extract the path
  const colonIndex = prediction.route.indexOf(':');
  const predictedMethod = prediction.route.slice(0, colonIndex);
  const predictedPath = prediction.route.slice(colonIndex + 1);

  // Only pre-fetch GET requests
  if (predictedMethod !== 'GET') return;

  logger.predict(
    req.originalUrl || req.url,
    predictedPath,
    prediction.probability,
  );

  prefetcher.schedule({
    predictedRoute: predictedPath,
    method: 'GET',
    clientId,
    port,
    forwardHeaders: {
      authorization: extractHeader(req, 'authorization'),
      cookie: extractHeader(req, 'cookie'),
      'x-session-id': extractHeader(req, 'x-session-id'),
    },
  });
}

function extractHeader(req: Request, name: string): string {
  const val = req.headers[name];
  if (!val) return '';
  return Array.isArray(val) ? val[0] ?? '' : val;
}

// ─── Re-exports ─────────────────────────────────────────────

export type { Prediction, GraphSnapshot } from './engine/MarkovGraph.js';
export type { CachedResponse, LRUCacheOptions } from './cache/LRUCache.js';
export type { LoggerOptions } from './utils/logger.js';
