/**
 * LRUCache — O(1) Predictive RAM Store with TTL
 *
 * Custom implementation using a Doubly Linked List + Hash Map
 * for O(1) get, put, and delete operations.
 *
 * Supports:
 * - Configurable maxSize (default: 500)
 * - TTL-based expiry (default: 15000ms)
 * - Per-user invalidation on state-mutating requests
 */

/** Doubly linked list node */
interface ListNode<V> {
  key: string;
  value: V;
  createdAt: number;
  prev: ListNode<V> | null;
  next: ListNode<V> | null;
}

export interface CachedResponse {
  status: number;
  headers: Record<string, string>;
  body: unknown;
  /** Time in ms the original DB/handler execution took */
  executionTimeMs: number;
  /** Timestamp when cached */
  cachedAt: number;
}

export interface LRUCacheOptions {
  maxSize?: number;
  ttlMs?: number;
}

export class LRUCache {
  private readonly maxSize: number;
  private readonly ttlMs: number;

  /** Hash map for O(1) key lookup */
  private readonly map: Map<string, ListNode<CachedResponse>> = new Map();

  /** Sentinel head/tail for the doubly linked list (MRU at head, LRU at tail) */
  private readonly head: ListNode<CachedResponse>;
  private readonly tail: ListNode<CachedResponse>;

  /** Cache statistics */
  private hits = 0;
  private misses = 0;
  private totalMsSaved = 0;

  constructor(options: LRUCacheOptions = {}) {
    this.maxSize = options.maxSize ?? 500;
    this.ttlMs = options.ttlMs ?? 15_000;

    // Sentinel nodes — never removed, simplify edge-case handling
    this.head = this.createNode('__HEAD__', null as unknown as CachedResponse);
    this.tail = this.createNode('__TAIL__', null as unknown as CachedResponse);
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  /**
   * Retrieve a cached response by key.
   * Returns null if the entry doesn't exist or has expired.
   * O(1) via hash map lookup + list move.
   */
  get(key: string): CachedResponse | null {
    const node = this.map.get(key);
    if (!node) {
      this.misses++;
      return null;
    }

    // Check TTL expiry
    if (Date.now() - node.createdAt > this.ttlMs) {
      this.removeNode(node);
      this.map.delete(key);
      this.misses++;
      return null;
    }

    // Move to head (most recently used)
    this.removeNode(node);
    this.addToHead(node);
    this.hits++;
    this.totalMsSaved += node.value.executionTimeMs;

    return node.value;
  }

  /**
   * Insert or update a cached response.
   * Evicts the LRU entry if at capacity.
   * O(1) via hash map + list operations.
   */
  put(key: string, value: CachedResponse): void {
    const existing = this.map.get(key);

    if (existing) {
      // Update existing entry
      existing.value = value;
      existing.createdAt = Date.now();
      this.removeNode(existing);
      this.addToHead(existing);
      return;
    }

    // Evict LRU entry if at capacity
    if (this.map.size >= this.maxSize) {
      const lru = this.tail.prev!;
      if (lru !== this.head) {
        this.removeNode(lru);
        this.map.delete(lru.key);
      }
    }

    // Insert new entry
    const node = this.createNode(key, value);
    this.addToHead(node);
    this.map.set(key, node);
  }

  /**
   * Delete a specific key from the cache.
   * O(1).
   */
  delete(key: string): boolean {
    const node = this.map.get(key);
    if (!node) return false;

    this.removeNode(node);
    this.map.delete(key);
    return true;
  }

  /**
   * Purge all cached predictions for a specific user.
   * Called on state-mutating requests (POST, PUT, PATCH, DELETE).
   *
   * Keys are composite: `${clientId}:${method}:${route}`
   * We iterate the map and remove all keys prefixed with the clientId.
   */
  invalidateUser(clientId: string): number {
    const prefix = `${clientId}:`;
    const keysToDelete: string[] = [];

    for (const key of this.map.keys()) {
      if (key.startsWith(prefix)) {
        keysToDelete.push(key);
      }
    }

    for (const key of keysToDelete) {
      this.delete(key);
    }

    return keysToDelete.length;
  }

  /**
   * Return current cache statistics.
   */
  getStats(): {
    size: number;
    maxSize: number;
    hits: number;
    misses: number;
    hitRate: number;
    totalMsSaved: number;
  } {
    const total = this.hits + this.misses;
    return {
      size: this.map.size,
      maxSize: this.maxSize,
      hits: this.hits,
      misses: this.misses,
      hitRate: total > 0 ? this.hits / total : 0,
      totalMsSaved: this.totalMsSaved,
    };
  }

  /**
   * Clear the entire cache.
   */
  clear(): void {
    this.map.clear();
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  // ─── Private Linked List Helpers ─────────────────────────────

  private createNode(key: string, value: CachedResponse): ListNode<CachedResponse> {
    return {
      key,
      value,
      createdAt: Date.now(),
      prev: null,
      next: null,
    };
  }

  /** Insert a node right after the head sentinel (MRU position). */
  private addToHead(node: ListNode<CachedResponse>): void {
    node.prev = this.head;
    node.next = this.head.next;
    this.head.next!.prev = node;
    this.head.next = node;
  }

  /** Unlink a node from the doubly linked list. */
  private removeNode(node: ListNode<CachedResponse>): void {
    if (node.prev) node.prev.next = node.next;
    if (node.next) node.next.prev = node.prev;
    node.prev = null;
    node.next = null;
  }
}
