/**
 * Identity — Session Tracking
 *
 * Deterministically identifies a user session by checking (in order):
 *   1. Custom `x-session-id` header
 *   2. Hashed `authorization` bearer token
 *   3. Session cookie (connect.sid / session)
 *   4. Fallback to req.ip
 *
 * Also maintains a lightweight TTL-bound Map tracking
 * clientId -> lastVisitedRoute for Markov transition recording.
 */

import { createHash } from 'node:crypto';
import type { Request } from 'express';

/** TTL for session-to-route tracking entries (10 minutes) */
const SESSION_TTL_MS = 10 * 60 * 1000;

/** Cleanup interval (every 2 minutes) */
const CLEANUP_INTERVAL_MS = 2 * 60 * 1000;

interface TrackedSession {
  lastRoute: string;
  expiresAt: number;
}

export class SessionTracker {
  private readonly sessions: Map<string, TrackedSession> = new Map();
  private cleanupTimer: ReturnType<typeof setInterval> | null = null;

  constructor() {
    // Periodic cleanup of expired entries
    this.cleanupTimer = setInterval(() => this.purgeExpired(), CLEANUP_INTERVAL_MS);
    // Ensure the timer doesn't prevent process exit
    if (this.cleanupTimer.unref) {
      this.cleanupTimer.unref();
    }
  }

  /**
   * Extract a deterministic client identifier from the request.
   */
  extractClientId(req: Request): string {
    // 1. Custom x-session-id header
    const sessionHeader = req.headers['x-session-id'];
    if (sessionHeader) {
      const val = Array.isArray(sessionHeader) ? sessionHeader[0] : sessionHeader;
      if (val) return `sid:${val}`;
    }

    // 2. Hashed authorization bearer token
    const authHeader = req.headers['authorization'];
    if (authHeader) {
      const val = Array.isArray(authHeader) ? authHeader[0] : authHeader;
      if (val && val.toLowerCase().startsWith('bearer ')) {
        const token = val.slice(7).trim();
        if (token) {
          const hash = createHash('sha256').update(token).digest('hex').slice(0, 16);
          return `auth:${hash}`;
        }
      }
    }

    // 3. Session cookie (connect.sid or session)
    const cookieHeader = req.headers['cookie'];
    if (cookieHeader) {
      const rawCookies = Array.isArray(cookieHeader) ? cookieHeader[0] : cookieHeader;
      if (rawCookies) {
        const sessionCookie = parseCookieValue(rawCookies, 'connect.sid')
          ?? parseCookieValue(rawCookies, 'session');
        if (sessionCookie) {
          const hash = createHash('sha256').update(sessionCookie).digest('hex').slice(0, 16);
          return `cookie:${hash}`;
        }
      }
    }

    // 4. Fallback to IP
    const ip = req.ip ?? req.socket?.remoteAddress ?? '127.0.0.1';
    return `ip:${ip}`;
  }

  /**
   * Get the last visited route for a given client.
   */
  getLastRoute(clientId: string): string | null {
    const entry = this.sessions.get(clientId);
    if (!entry) return null;
    if (Date.now() > entry.expiresAt) {
      this.sessions.delete(clientId);
      return null;
    }
    return entry.lastRoute;
  }

  /**
   * Update the last visited route for a given client.
   */
  setLastRoute(clientId: string, route: string): void {
    this.sessions.set(clientId, {
      lastRoute: route,
      expiresAt: Date.now() + SESSION_TTL_MS,
    });
  }

  /**
   * Remove expired session entries.
   */
  private purgeExpired(): void {
    const now = Date.now();
    for (const [key, entry] of this.sessions) {
      if (now > entry.expiresAt) {
        this.sessions.delete(key);
      }
    }
  }

  /**
   * Tear down the cleanup timer (for graceful shutdown).
   */
  destroy(): void {
    if (this.cleanupTimer) {
      clearInterval(this.cleanupTimer);
      this.cleanupTimer = null;
    }
  }
}

/**
 * Parse a specific cookie value from the raw Cookie header string.
 */
function parseCookieValue(cookieString: string, name: string): string | null {
  const cookies = cookieString.split(';');
  for (const cookie of cookies) {
    const [key, ...rest] = cookie.trim().split('=');
    if (key === name) {
      const value = rest.join('=');
      return value ? decodeURIComponent(value) : null;
    }
  }
  return null;
}
